    conv2d_4_output_array.data_start = AI_PTR(g_echodscnn_activations_map[0] + 6960);
    conv2d_6_pad_before_output_array.data = AI_PTR(g_echodscnn_activations_map[0] + 1200);
    conv2d_6_pad_before_output_array.data_start = AI_PTR(g_echodscnn_activations_map[0] + 1200);
    conv2d_6_scratch0_array.data = AI_PTR(g_echodscnn_activations_map[0] + 21360);
    conv2d_6_scratch0_array.data_start = AI_PTR(g_echodscnn_activations_map[0] + 21360);
    conv2d_6_output_array.data = AI_PTR(g_echodscnn_activations_map[0] + 0);
    conv2d_6_output_array.data_start = AI_PTR(g_echodscnn_activations_map[0] + 0);
    nl_6_nl_output_array.data = AI_PTR(g_echodscnn_activations_map[0] + 20840);
